CREATE TABLE "EodScanPlan" ("id" UUID PRIMARY KEY,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "EodScanItem" ("id" TEXT PRIMARY KEY,"scanId" UUID NOT NULL REFERENCES "EodScanPlan"("id"),"evidence" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "EodScanItem_scanId" ON "EodScanItem"("scanId");
CREATE TABLE "EodScanCheckpoint" ("itemId" TEXT PRIMARY KEY REFERENCES "EodScanItem"("id"),"evidence" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "EodScanDispatch" ("itemId" TEXT PRIMARY KEY REFERENCES "EodScanItem"("id"),"state" TEXT NOT NULL,"checkedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER immutable_eod_plan BEFORE UPDATE OR DELETE ON "EodScanPlan" FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER immutable_eod_item BEFORE UPDATE OR DELETE ON "EodScanItem" FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER immutable_eod_checkpoint BEFORE UPDATE OR DELETE ON "EodScanCheckpoint" FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
